// ERP feed: erp_pm_stock
// Expected columns from ERP: Item Code, Item Description, Site, Location, Opening...
//
// Adapt the input parsing below to match your ERP's actual response format.
// The output must be a single item with {report_key, rows, meta}.

const input = $input.first().json;

// --- ADAPT THIS SECTION ---
// If your ERP returns {data: [{...}, ...]}:
let rawRows = input.data || input.rows || input.results || [];

// If the response IS the array directly:
if (Array.isArray(input)) rawRows = input;

// --- END ADAPT ---

const expectedColumns = [
  "Item Code",
  "Item Description",
  "Site",
  "Location",
  "Opening",
  "Receipt",
  "Issued",
  "Closing",
  "UOM",
  "Safety Stock",
  "Reorder Qty",
  "Lead Time Days",
  "Daily Consumption",
  "Green Level",
  "Yellow Level",
  "Red Level",
  "Current Stock in Kg",
  "Current Stock Days",
  "To Be Ordered Qty",
  "Rate",
  "Amount",
  "Category",
  "Item Type"
];

// Clean rows: trim strings, remove fully-empty rows
const cleanedRows = [];
for (const raw of rawRows) {
  const row = {};
  let hasValue = false;

  for (const [key, value] of Object.entries(raw)) {
    const cleanKey = String(key).replace(/\r|\n/g, ' ').replace(/\s+/g, ' ').trim();
    if (!cleanKey) continue;

    if (value === null || value === undefined) continue;
    const strVal = String(value).trim();
    if (strVal === '') continue;

    row[cleanKey] = value;
    hasValue = true;
  }

  if (hasValue) cleanedRows.push(row);
}

// Build the payload for Django's /api/ppc-data/erp-landing/
return [{
  json: {
    report_key: 'erp_pm_stock',
    rows: cleanedRows,
    meta: {
      pulled_at: new Date().toISOString(),
      report_name: 'erp_pm_stock',
      row_count: cleanedRows.length,
      source: 'n8n_scheduled',
    }
  }
}];
